/**
 * Bundle fork lens CSS into config/bundled_lenses.js for the editor build.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const LENSES_DIR = path.join(ROOT, 'lenses');
const OUT = path.join(ROOT, 'config', 'bundled_lenses.js');

/** @type {const} */
const MANIFEST = [
    { id: 'bundled-quebec', nameKey: 'quebec', file: 'quebec.css' },
    { id: 'bundled-quebec-surfaces', nameKey: 'quebec_surfaces', file: 'quebec-surfaces.css' },
    { id: 'bundled-maxspeed-colors', nameKey: 'maxspeed_colors', file: 'maxspeed-colors.css' }
];

const DEFAULT_BUNDLED_LENS_ID = 'bundled-quebec';
const SURFACE_COLOURS_LENS_ID = 'bundled-quebec-surfaces';

const bundled = MANIFEST.map(({ id, nameKey, file }) => ({
    id,
    nameKey,
    css: fs.readFileSync(path.join(LENSES_DIR, file), 'utf8')
}));

const out = `// Generated by scripts/build_bundled_lenses.js — do not edit.
export const DEFAULT_BUNDLED_LENS_ID = ${JSON.stringify(DEFAULT_BUNDLED_LENS_ID)};
export const SURFACE_COLOURS_LENS_ID = ${JSON.stringify(SURFACE_COLOURS_LENS_ID)};

export const BUNDLED_LENSES = ${JSON.stringify(bundled, null, 2)};
`;

fs.writeFileSync(OUT, out);
